files.content:
:root {
  --bg: #1f2430;
  --card: #2b3245;
  --accent: #ffb347;
  --good: #6ee7a8;
  --bad: #ff6b6b;
  --text: #f4f6fb;
  --muted: #a9b1c9;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: radial-gradient(circle at 50% 20%, #2f3a55, var(--bg));
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.board {
  width: 100%;
  max-width: 420px;
  background: var(--card);
  border-radius: 20px;
  padding: 28px 22px;
  box-shadow: 0 18px 40px rgba(0,0,0,.4);
  display: flex;
  flex-direction: column;
  gap: 22px;
}

.title {
  margin: 0;
  text-align: center;
  font-size: 1.6rem;
  letter-spacing: 1px;
  color: var(--accent);
}

.pet-area {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 14px;
}

.pet {
  position: relative;
  width: 120px;
  height: 120px;
  image-rendering: pixelated;
}

.head {
  position: absolute;
  inset: 10px 0 0 0;
  background: var(--accent);
  border-radius: 14px;
  transition: background .3s;
}

.ear {
  position: absolute;
  top: 0;
  width: 26px;
  height: 30px;
  background: var(--accent);
  border-radius: 6px 6px 0 0;
  transition: background .3s;
}
.ear.left { left: 8px; }
.ear.right { right: 8px; }

.eye {
  position: absolute;
  top: 34px;
  width: 14px;
  height: 14px;
  background: var(--bg);
  border-radius: 50%;
  transition: all .25s;
}
.eye.left { left: 26px; }
.eye.right { right: 26px; }

.mouth {
  position: absolute;
  bottom: 22px;
  left: 50%;
  transform: translateX(-50%);
  width: 30px;
  height: 14px;
  border-bottom: 4px solid var(--bg);
  border-radius: 0 0 16px 16px;
  transition: all .25s;
}

.blush {
  position: absolute;
  bottom: 30px;
  width: 14px;
  height: 8px;
  background: rgba(255,107,107,.6);
  border-radius: 50%;
  opacity: 0;
  transition: opacity .25s;
}
.blush.left { left: 16px; }
.blush.right { right: 16px; }

/* Mood variants */
.pet[data-mood="happy"] .blush { opacity: 1; }
.pet[data-mood="sad"] .mouth {
  border-bottom: 0;
  border-top: 4px solid var(--bg);
  border-radius: 16px 16px 0 0;
  bottom: 26px;
}
.pet[data-mood="sad"] .eye { top: 40px; }
.pet[data-mood="sleepy"] .eye { height: 4px; top: 40px; border-radius: 2px; }
.pet[data-mood="sleepy"] .mouth { width: 16px; height: 8px; }
.pet[data-mood="sleepy"] .head,
.pet[data-mood="sleepy"] .ear { background: #c98d3a; }

.mood {
  margin: 0;
  font-size: 1.05rem;
  color: var(--muted);
  text-align: center;
  min-height: 1.4em;
}

.stats {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.stat { display: flex; flex-direction: column; gap: 6px; }

.stat-label {
  font-size: .95rem;
  color: var(--muted);
  font-weight: 600;
}

.bar {
  height: 16px;
  background: rgba(0,0,0,.35);
  border-radius: 10px;
  overflow: hidden;
}

.fill {
  height: 100%;
  width: 70%;
  border-radius: 10px;
  transition: width .35s ease, background .3s;
}

.fill.hunger { background: var(--accent); }
.fill.happy { background: var(--good); }
.fill.energy { background: #5aa9ff; }

.fill.low { background: var(--bad) !important; }

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

.btn {
  flex: 1 1 0;
  min-width: 90px;
  padding: 14px 10px;
  font-size: 1rem;
  font-weight: 600;
  font-family: inherit;
  color: var(--bg);
  background: var(--accent);
  border: 2px solid transparent;
  border-radius: 12px;
  cursor: pointer;
  transition: transform .1s, filter .15s, box-shadow .15s;
}

.btn.play { background: var(--good); }
.btn.sleep { background: #5aa9ff; }

.btn:hover { filter: brightness(1.1); }
.btn:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 2px;
  border-color: var(--text);
}
.btn:active { transform: scale(.96); filter: brightness(.92); }

@media (max-width: 380px) {
  .board { padding: 22px 16px; }
  .title { font-size: 1.4rem; }
  .btn { min-width: 0; padding: 12px 8px; }
}

(function () {
  "use strict";

  var state = { hunger: 70, happiness: 70, energy: 70 };

  var els = {
    pet: document.getElementById("pet"),
    mood: document.getElementById("mood"),
    hungerFill: document.getElementById("hunger-fill"),
    happyFill: document.getElementById("happy-fill"),
    energyFill: document.getElementById("energy-fill"),
    hungerBar: document.getElementById("hunger-bar"),
    happyBar: document.getElementById("happy-bar"),
    energyBar: document.getElementById("energy-bar"),
    feed: document.getElementById("feed"),
    play: document.getElementById("play"),
    sleep: document.getElementById("sleep")
  };

  function clamp(n) {
    return Math.max(0, Math.min(100, Math.round(n)));
  }

  function moodFor() {
    if (state.energy < 25) return "sleepy";
    if (state.hunger < 25 || state.happiness < 25) return "sad";
    if (state.hunger > 70 && state.happiness > 70 && state.energy > 50) return "happy";
    return "neutral";
  }

  var moodText = {
    happy: "Your pet is happy!",
    neutral: "Your pet is doing okay.",
    sad: "Your pet looks sad. Try feeding or playing.",
    sleepy: "Your pet is sleepy. Time for a nap!"
  };

  function render() {
    var values = [
      [els.hungerFill, els.hungerBar, state.hunger],
      [els.happyFill, els.happyBar, state.happiness],
      [els.energyFill, els.energyBar, state.energy]
    ];
    values.forEach(function (v) {
      v[0].style.width = v[2] + "%";
      v[1].setAttribute("aria-valuenow", String(v[2]));
      v[0].classList.toggle("low", v[2] < 25);
    });

    var mood = moodFor();
    els.pet.setAttribute("data-mood", mood);
    els.mood.textContent = moodText[mood];
  }

  function action(fn) {
    fn();
    state.hunger = clamp(state.hunger);
    state.happiness = clamp(state.happiness);
    state.energy = clamp(state.energy);
    render();
  }

  els.feed.addEventListener("click", function () {
    action(function () {
      state.hunger += 20;
      state.happiness += 5;
      state.energy -= 5;
    });
  });

  els.play.addEventListener("click", function () {
    action(function () {
      state.happiness += 20;
      state.energy -= 15;
      state.hunger -= 10;
    });
  });

  els.sleep.addEventListener("click", function () {
    action(function () {
      state.energy += 25;
      state.hunger -= 5;
      state.happiness -= 2;
    });
  });

  render();
})();
